select m83_assert((select count(*)=1 from private.prisma_token_lots where organization_id=m83_id('calendar') and source='monthly'),'migration does not duplicate franchise');
select m83_assert(not exists(select * from cw_monthly except select id,total,remaining from private.prisma_token_lots),'monthly identity amount and remaining preserved');
select m83_assert(not exists(select * from cw_quotes except select * from private.prisma_token_quotes),'quotes immutable across migration');
select m83_assert(not exists(select * from cw_reservations except select * from private.prisma_token_reservations),'reservations immutable across migration');
select m83_assert(not exists(select * from cw_allocations except select * from private.prisma_token_allocations),'old allocations preserved');
select m83_assert(not exists(select * from cw_debits except select * from private.prisma_token_movements),'debit history immutable');
select m83_assert(not exists(select * from cw_rates except select * from private.prisma_token_rates),'all tariffs unchanged');
select m83_assert((select expired and expires_at=created_at+interval '720 hours' from private.prisma_token_lots where id=m83_id('old-additional')),'legacy additional expires from original acquisition no grace restart');
select m83_assert((select bool_and(extract(day from current_period)=1 and extract(day from next_period)=1 and pending_cycle_day is null and policy_version='prisma-token-policy-2.0.0') from private.prisma_token_accounts),'all account cycles calendar based');
select m83_assert((select bool_and(validity_days=30) from private.prisma_token_packages),'every package has fixed30days');
select m83_assert(public.prisma_tokens('overview',m83_id('calendar'))->>'contract'='prisma-tokens-2.0.0','management contract explicitly versioned');
select m83_assert(public.prisma_tokens('quote',m83_id('calendar'),'{"functionName":"profile_synthesis","quantity":1}')->>'contract'='prisma-token-quote-1.0.0','consumer quote contract preserved');
insert into cw_state values('activity',public.prisma_tokens('quote',m83_id('calendar'),'{"functionName":"assessment_activity_analysis","quantity":1}'));
select private.prisma_token_reserve(m83_id('calendar'),'assessment_activity_analysis',m83_id('calendar-activity'),(select (value->>'id')::uuid from cw_state where key='activity'),1);
select private.prisma_token_settle(m83_id('calendar'),'assessment_activity_analysis',m83_id('calendar-activity'),true);
select private.prisma_token_settle(m83_id('calendar'),'assessment_activity_analysis',m83_id('calendar-activity'),true);
select m83_assert((select count(*)=1 and sum(amount)=-6193 from private.prisma_token_movements where kind='debit' and function_name='assessment_activity_analysis' and organization_id=m83_id('calendar')),'fourth consumer analysis preserves price and exactly-once debit');
select m83_assert(jsonb_array_length(public.prisma_tokens('overview',m83_id('calendar'))#>'{planning,daily_consumption}')=30,'planning includes zero days in full30day server series');
select private.prisma_token_settle(m83_id('calendar'),'parser_ia',m83_id('old-calendar-reservation'),true);
select private.prisma_token_settle(m83_id('calendar'),'parser_ia',m83_id('old-calendar-reservation'),true);
select m83_assert((select count(*)=1 from private.prisma_token_movements where kind='debit' and reference_id=(select id from private.prisma_token_reservations where operation_id=m83_id('old-calendar-reservation'))),'old reservation settles once at original value');
select m83_assert((select amount=(select (value->>'amount')::bigint from cw_state where key='old-quote') from private.prisma_token_reservations where operation_id=m83_id('old-calendar-reservation')),'frozen quote unchanged after policy');
select m83_reject('select public.prisma_tokens(''configure'',m83_id(''calendar''),''{"monthlyTokens":1000000,"cycleDay":15}'')','22023');
select m83_reject('select public.prisma_tokens(''save_package'',null,''{"name":"Forbidden months","tokens":1,"priceCents":1,"validityMonths":12}'')','22023');
select m83_reject('select public.prisma_tokens(''save_package'',null,''{"name":"Forbidden days","tokens":1,"priceCents":1,"validityDays":31}'')','22023');
-- A package expiring earlier must still wait until monthly credit is exhausted.
insert into private.prisma_token_lots(id,organization_id,source,source_key,total,remaining,expires_at)
 values(m83_id('early-extra'),m83_id('calendar'),'additional','synthetic-early',100000,100000,now()+interval '1 day'),
 (m83_id('later-extra'),m83_id('calendar'),'additional','synthetic-later',100000,100000,now()+interval '2 days');
update private.prisma_token_lots set remaining=5000 where organization_id=m83_id('calendar') and source='monthly';
insert into cw_state values('split',public.prisma_tokens('quote',m83_id('calendar'),'{"functionName":"parser_ia","quantity":1}'));
select private.prisma_token_reserve(m83_id('calendar'),'parser_ia',m83_id('split-reserve'),(select (value->>'id')::uuid from cw_state where key='split'),1);
select m83_assert((select al.amount=5000 from private.prisma_token_allocations al join private.prisma_token_lots l on l.id=al.lot_id join private.prisma_token_reservations r on r.id=al.reservation_id where r.operation_id=m83_id('split-reserve') and l.source='monthly'),'franchise fully allocated first');
select m83_assert((select sum(al.amount)=r.amount-5000 from private.prisma_token_allocations al join private.prisma_token_reservations r on r.id=al.reservation_id where r.operation_id=m83_id('split-reserve') and al.lot_id=m83_id('early-extra') group by r.amount),'earliest additional supplies exact remainder');
select m83_assert(not exists(select 1 from private.prisma_token_allocations al join private.prisma_token_reservations r on r.id=al.reservation_id where r.operation_id=m83_id('split-reserve') and al.lot_id=m83_id('later-extra')),'later additional waits');
select private.prisma_token_reserve(m83_id('calendar'),'parser_ia',m83_id('split-reserve'),(select (value->>'id')::uuid from cw_state where key='split'),1);
select m83_assert((select count(*)=1 from private.prisma_token_reservations where operation_id=m83_id('split-reserve')),'reservation replay idempotent');
select private.prisma_token_settle(m83_id('calendar'),'parser_ia',m83_id('split-reserve'),false);
select m83_assert((select remaining=5000 from private.prisma_token_lots where organization_id=m83_id('calendar') and source='monthly'),'failure releases without consuming lot');
select m83_reject('select private.prisma_token_settle(m83_id(''calendar''),''parser_ia'',m83_id(''split-reserve''),true)','40001');
insert into cw_state values('order',public.prisma_tokens('request_package',m83_id('calendar'),jsonb_build_object('packageId',(select id from private.prisma_token_packages where active and effective_at<=now() limit 1),'operationId',m83_id('calendar-order'))));
select m83_assert(not exists(select 1 from private.prisma_token_lots where source_key='order:'||m83_id('calendar-order')),'request grants nothing');
select m83_reject('select public.prisma_tokens(''order_status'',m83_id(''calendar''),jsonb_build_object(''id'',m83_id(''calendar-order''),''status'',''released'',''paymentConfirmed'',true,''paymentReference'',''synthetic''))','22023');
select public.prisma_tokens('order_status',m83_id('calendar'),jsonb_build_object('id',m83_id('calendar-order'),'status','awaiting_payment'));
select m83_reject('select public.prisma_tokens(''order_status'',m83_id(''calendar''),jsonb_build_object(''id'',m83_id(''calendar-order''),''status'',''released''))','22023');
select public.prisma_tokens('order_status',m83_id('calendar'),jsonb_build_object('id',m83_id('calendar-order'),'status','released','paymentConfirmed',true,'paymentReference','synthetic-LOCAL-only'));
select public.prisma_tokens('order_status',m83_id('calendar'),jsonb_build_object('id',m83_id('calendar-order'),'status','released','paymentConfirmed',true,'paymentReference','synthetic-LOCAL-only'));
select m83_assert((select count(*)=1 and bool_and(expires_at=o.released_at+interval '720 hours') from private.prisma_token_lots l join private.prisma_token_orders o on 'order:'||o.id=l.source_key where o.id=m83_id('calendar-order')),'verified payment releases exactly once for exact720hours');
set local role authenticated;
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
select m83_reject('select public.prisma_tokens(''overview'',m83_id(''calendar''))','42501');
select m83_assert(public.prisma_tokens('overview',m83_id('a'))->'planning'='null' and public.prisma_tokens('overview',m83_id('a'))->'packages'='[]','operator cannot see company planning or financial catalog');
select m83_reject('select * from private.prisma_token_lots','42501');
select m83_reject('select private.prisma_token_planning_data(m83_id(''a''))','42501');
select m83_reject('select private.prisma_token_movement_details(null,null,true)','42501');
select m83_reject('select public.prisma_tokens(''platform'')','42501');
select set_config('request.jwt.claims','{"role":"authenticated","user_metadata":{"access_profile":"super_admin"}}',true);
select m83_reject('select public.prisma_tokens(''platform'')','42501');
select set_config('request.jwt.claims','{}',true);
-- Existing organization fixtures/owner propagation may grant B; remove that synthetic membership for a genuine non-member case.
reset role;
delete from public.organization_memberships where organization_id=m83_id('b') and user_id=m83_id('owner');
set local role authenticated;
select set_config('request.jwt.claim.sub',m83_id('owner')::text,true);
select m83_assert(public.prisma_tokens('overview',m83_id('a'))->>'manager'='true' and public.prisma_tokens('overview',m83_id('a'))#>>'{planning,method}'='prisma-token-planning-1.0.0','owner sees own company planning');
select m83_reject('select public.prisma_tokens(''overview'',m83_id(''b''))','42501');
select set_config('request.jwt.claim.sub',m83_id('inactive')::text,true);
select m83_reject('select public.prisma_tokens(''overview'',m83_id(''a''))','42501');
reset role;set local role anon;
select m83_reject('select public.prisma_tokens(''overview'',m83_id(''a''))','42501');
reset role;select set_config('request.jwt.claim.sub',m83_id('super')::text,true);
select m83_assert((select people is not distinct from (select jsonb_agg(to_jsonb(x) order by id) from public.people x) and profiles is not distinct from (select jsonb_agg(to_jsonb(x) order by id) from public.professional_profiles x) and assessments is not distinct from (select jsonb_agg(to_jsonb(x) order by id) from public.position_assessments x) and matching is not distinct from (select jsonb_agg(to_jsonb(x) order by id) from public.match_evaluations x) from cw_protected),'people profiles assessments and matching preserved');
-- Private deterministic clocks, separate organizations; no public clock override.
insert into public.organizations(id,name,group_id) values(m83_id('expired-pending'),'Expired pending fixture',m83_id('group'));
select private.prisma_token_ensure(m83_id('expired-pending'));
insert into cw_state values('held-failure',public.prisma_tokens('quote',m83_id('expired-pending'),'{"functionName":"parser_ia","quantity":1}')),('held-success',public.prisma_tokens('quote',m83_id('expired-pending'),'{"functionName":"profile_synthesis","quantity":1}'));
select private.prisma_token_reserve(m83_id('expired-pending'),'parser_ia',m83_id('held-failure'),(select (value->>'id')::uuid from cw_state where key='held-failure'),1);
select private.prisma_token_reserve(m83_id('expired-pending'),'profile_synthesis',m83_id('held-success'),(select (value->>'id')::uuid from cw_state where key='held-success'),1);
update private.prisma_token_lots set expires_at=now()-interval '1 second' where organization_id=m83_id('expired-pending');
select private.prisma_token_ensure(m83_id('expired-pending'));
select m83_assert(private.prisma_token_balance(m83_id('expired-pending'))=0 and (select not expired from private.prisma_token_lots where organization_id=m83_id('expired-pending')),'expired lot excluded but held reservations remain settleable');
select private.prisma_token_settle(m83_id('expired-pending'),'parser_ia',m83_id('held-failure'),false);
select private.prisma_token_settle(m83_id('expired-pending'),'profile_synthesis',m83_id('held-success'),true);
select m83_assert(private.prisma_token_balance(m83_id('expired-pending'))=0 and (select expired from private.prisma_token_lots where organization_id=m83_id('expired-pending')),'late failure cannot restore expired credit and successful delivery still settles');
insert into public.organizations(id,name,group_id) values(m83_id('clock-leap'),'Clock leap',m83_id('group')),(m83_id('clock-year'),'Clock year',m83_id('group'));
select private.prisma_token_ensure(m83_id('clock-leap'),'2024-02-29T23:59:59-03:00');
select m83_assert((select current_period='2024-02-01' and next_period='2024-03-01' from private.prisma_token_accounts where organization_id=m83_id('clock-leap')),'leap-month activation receives calendar franchise');
select private.prisma_token_ensure(m83_id('clock-leap'),'2024-03-01T02:59:59Z');
select m83_assert((select count(*)=1 from private.prisma_token_lots where organization_id=m83_id('clock-leap')),'UTC March still February in Brasilia does not renew');
select private.prisma_token_ensure(m83_id('clock-leap'),'2024-03-01T03:00:00Z');
select private.prisma_token_ensure(m83_id('clock-leap'),'2024-03-01T03:00:00Z');
select m83_assert((select current_period='2024-03-01' and next_period='2024-04-01' from private.prisma_token_accounts where organization_id=m83_id('clock-leap')),'exact Brasilia boundary renews');
select m83_assert((select count(*)=2 and count(*) filter(where expired)=1 from private.prisma_token_lots where organization_id=m83_id('clock-leap')),'boundary repeat grants once and expires previous month');
select private.prisma_token_ensure(m83_id('clock-leap'),'2024-07-15T10:00:00-03:00');
select m83_assert((select count(*)=3 from private.prisma_token_lots where organization_id=m83_id('clock-leap')),'skipped months do not backfill');
select m83_assert((select total=1000000 and expires_at='2024-08-01T00:00:00-03:00' from private.prisma_token_lots where organization_id=m83_id('clock-leap') and source_key='month:2024-07-01'),'partial month grants full1M until next first');
select private.prisma_token_ensure(m83_id('clock-year'),'2026-12-31T23:59:59-03:00');
update private.prisma_token_accounts set pending_monthly_tokens=2000000 where organization_id=m83_id('clock-year');
select private.prisma_token_ensure(m83_id('clock-year'),'2027-01-01T00:00:00-03:00');
select m83_assert((select next_period='2027-02-01' from private.prisma_token_accounts where organization_id=m83_id('clock-year')),'December January rollover correct');
select m83_assert((select total=2000000 from private.prisma_token_lots where organization_id=m83_id('clock-year') and source_key='month:2027-01-01'),'scheduled quota applies at next calendar month');
select m83_reject('select private.prisma_token_ensure(m83_id(''clock-year''),''2026-12-01T00:00:00-03:00'')','22023');
